		WorldGen.TileFrame((i + 1) | 0, (j - 1) | 0, false, false);
		WorldGen.TileFrame((i + 1) | 0, j, false, false);
		WorldGen.TileFrame((i + 1) | 0, (j + 1) | 0, false, false);
